//! Prometheus metrics for Kiln server.
//!
//! Exposes metrics in the standard Prometheus text exposition format
//! via the /metrics endpoint.

use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};
use std::sync::Arc;

/// Prometheus metrics state.
///
/// All metrics are stored atomically for thread-safe access.
#[derive(Debug, Clone)]
pub struct Metrics {
    /// Inference request counters
    requests_total: AtomicU64,
    /// Request duration histogram (count + sum only, no buckets)
    request_duration_count: AtomicU64,
    request_duration_sum: AtomicU64,
    /// Total tokens generated across all requests
    tokens_generated: AtomicU64,
    /// Currently in-flight requests
    active_requests: AtomicUsize,
    /// Scheduler metrics
    scheduler_waiting: AtomicUsize,
    scheduler_running: AtomicUsize,
    blocks_used: AtomicUsize,
    blocks_total: AtomicUsize,
    /// GPU memory metrics
    vram_total_bytes: AtomicU64,
    vram_model_bytes: AtomicU64,
    vram_kv_cache_bytes: AtomicU64,
    vram_training_budget_bytes: AtomicU64,
    /// Training metrics
    training_jobs_total: AtomicU64,
    training_active: AtomicUsize,
    /// Adapter metrics
    active_adapter: Arc<std::sync::RwLock<Option<String>>>,
}

impl Metrics {
    /// Create new Metrics with zeroed counters.
    pub fn new() -> Self {
        Self {
            requests_total: AtomicU64::new(0),
            request_duration_count: AtomicU64::new(0),
            request_duration_sum: AtomicU64::new(0),
            tokens_generated: AtomicU64::new(0),
            active_requests: AtomicUsize::new(0),
            scheduler_waiting: AtomicUsize::new(0),
            scheduler_running: AtomicUsize::new(0),
            blocks_used: AtomicUsize::new(0),
            blocks_total: AtomicUsize::new(0),
            vram_total_bytes: AtomicU64::new(0),
            vram_model_bytes: AtomicU64::new(0),
            vram_kv_cache_bytes: AtomicU64::new(0),
            vram_training_budget_bytes: AtomicU64::new(0),
            training_jobs_total: AtomicU64::new(0),
            training_active: AtomicUsize::new(0),
            active_adapter: Arc::new(std::sync::RwLock::new(None)),
        }
    }

    /// Increment request counter.
    pub fn inc_requests(&self, status: &str) {
        self.requests_total.fetch_add(1, Ordering::Relaxed);
    }

    /// Record request duration (seconds).
    pub fn observe_duration(&self, duration_secs: f64) {
        let count = self.request_duration_count.fetch_add(1, Ordering::Relaxed);
        let sum = self.request_duration_sum.fetch_add(duration_secs, Ordering::Relaxed);
        self.request_duration_count.fetch_add(0, Ordering::Relaxed);
        self.request_duration_sum.fetch_add(sum, Ordering::Relaxed);
    }

    /// Increment token counter.
    pub fn inc_tokens(&self, n: usize) {
        self.tokens_generated.fetch_add(n as u64, Ordering::Relaxed);
    }

    /// Increment active requests counter.
    pub fn inc_active(&self) {
        self.active_requests.fetch_add(1, Ordering::Relaxed);
    }

    /// Decrement active requests counter.
    pub fn dec_active(&self) {
        self.active_requests.fetch_sub(1, Ordering::Relaxed);
    }

    /// Set scheduler metrics.
    pub fn set_scheduler(&self, waiting: usize, running: usize, blocks_used: usize, blocks_total: usize) {
        self.scheduler_waiting.store(waiting, Ordering::Relaxed);
        self.scheduler_running.store(running, Ordering::Relaxed);
        self.blocks_used.store(blocks_used, Ordering::Relaxed);
        self.blocks_total.store(blocks_total, Ordering::Relaxed);

